SELECT ProdutoCodigo,  max(idProduto) FROM Produto
GROUP BY ProdutoCodigo
HAVING count(*) > 1

delete Produto
  from
  (
     select ProdutoCodigo as codigo
	        ,min(idProduto) as id
	   from Produto
      group by ProdutoCodigo
     having count(*) > 1
  ) tab
 where idProduto > tab.id
       and ProdutoCodigo=tab.codigo




